    var canon = canonSkillName(nm, cat);
    /* 선봉장 · 컨택트히터의 옛 이름(타순배치)은 새 이름(타순O / 타순X)으로 (ORDER_RENAME, 2026-10-23) */
    if(cat === "타자") canon = orderRename(canon);
