function distValueAt(arr, top) {
  if (!arr || !arr.length) return null;
  var x = (100 - top) / 100 * (arr.length - 1);
  if (x <= 0) return arr[0];
  if (x >= arr.length - 1) return arr[arr.length - 1];
  var lo = Math.floor(x), hi = lo + 1;
  return arr[lo] + (arr[hi] - arr[lo]) * (x - lo);
}
